'use strict';
const systemStarted=Date.now(),processes=new Map(),windowResources=new Map();
let fsReady=false,fsFailure='',fileLocation=null,fileBack=[],fileForward=[],fileSelection=new Set(),clipboard=null,fileView=read('file-view','grid'),fileSort='name',fileQuery='',editorFile=null,editorDirty=false,previewFile=null,settingsSection='appearance';
const sizeLabel=n=>{if(!Number.isFinite(n))return 'Недоступно';const units=['Б','КБ','МБ','ГБ','ТБ'];let i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return n.toLocaleString('ru-RU',{maximumFractionDigits:i?1:0})+' '+units[i]};
function reportError(e){console.error(e);toast(e?.name==='QuotaExceededError'?'Недостаточно места в хранилище браузера. Освободите место или скачайте файлы.':e.message||'Не удалось выполнить операцию')}
function act(fn){return async(...args)=>{try{return await fn(...args)}catch(e){reportError(e)}}}
function glyph(n){if(n.kind==='disk')return '◉';if(n.kind==='folder')return '▰';if(n.type?.startsWith('image/'))return '▧';if(n.type?.startsWith('audio/'))return '♫';if(n.type?.startsWith('video/'))return '▷';return '▤'}
function diskRoot(){return VFS.model.all().find(n=>n.kind==='disk'&&n.system)?.id}
