function refreshDock(){const ids=['files','browser','notes','calendar','music','terminal','tasks','settings','trash'];$('#dock').innerHTML=ids.map(id=>`<button class="dock-item ${wins[id]?'running':''}" data-app="${id}" aria-label="${esc(apps[id].name)}"><span class="app-icon">${apps[id].icon}</span></button>`).join('')+'<button class="dock-item" id="all-apps" aria-label="Все приложения"><span class="app-icon">⠿</span></button>';$$('[data-app]',$('#dock')).forEach(b=>b.onclick=()=>openApp(b.dataset.app));$('#all-apps').onclick=spotlight}
Object.assign(apps,{tasks:{name:'Диспетчер',icon:'▥'},editor:{name:'Текстовый редактор',icon:'✎'},preview:{name:'Просмотр',icon:'▧'}});
const originalOpenApp=openApp,originalRenderApp=renderApp;
openApp=function(id){if(!apps[id])return;if(['files','trash','editor','preview','terminal'].includes(id)&&!fsReady){toast(fsFailure||'Подготовка файловой системы…');return}const exists=!!wins[id];originalOpenApp(id);const w=wins[id];if(!w||exists)return;processes.set(id,{started:Date.now(),pid:Math.floor(performance.now())});w.style.left=Math.max(8,Math.min(innerWidth-w.offsetWidth-8,w.offsetLeft))+'px';if(['files','browser','settings','tasks'].includes(id)){w.style.width=Math.min(920,innerWidth-40)+'px';w.style.height=Math.min(610,innerHeight-160)+'px';w.style.left=Math.max(8,(innerWidth-w.offsetWidth)/2)+'px'}
  const close=$('[data-window-action="close"]',w);close.onclick=()=>closeApp(id);const min=$('[data-window-action="minimize"]',w);min.onclick=()=>{w.style.display='none';syncActiveApp();rememberSession()};
  w.addEventListener('pointerup',rememberSession);w.addEventListener('keydown',e=>{if(e.altKey&&e.key==='F4'){e.preventDefault();closeApp(id)}});refreshDock();rememberSession();
};
renderApp=function(id){const handlers={files:()=>renderFiles(false),trash:()=>renderFiles(true),settings:renderSettings,terminal:renderTerminal,browser:renderBrowser,tasks:renderTasks,editor:renderEditor,preview:renderPreview};(handlers[id]||(()=>originalRenderApp(id)))()};
function syncActiveApp(){const entry=Object.entries(wins).filter(([,w])=>w.style.display!=='none').sort((a,b)=>(+b[1].style.zIndex)-(+a[1].style.zIndex))[0];focused=entry?.[0]||null;$('#active-app').textContent=entry?apps[entry[0]].name:'Forma'}
function disposeWindow(id){for(const url of windowResources.get(id)||[])URL.revokeObjectURL(url);windowResources.delete(id);if(id==='browser'){for(const t of browserTabs)t.frame?.remove();browserTabs=[]}if(id==='music')$('audio',wins[id])?.pause();if(id==='editor'){editorFile=null;editorDirty=false}wins[id]?.remove();delete wins[id];processes.delete(id);refreshDock();syncActiveApp();rememberSession()}
function closeApp(id){if(!wins[id])return;if(id==='editor'&&editorDirty){confirmDialog('Закрыть без сохранения?','Изменения в текстовом редакторе ещё не записаны в файл.',()=>disposeWindow(id));return}disposeWindow(id)}
function ownUrl(id,blob){const url=URL.createObjectURL(blob);if(!windowResources.has(id))windowResources.set(id,[]);windowResources.get(id).push(url);return url}
function rememberSession(){save('session',Object.entries(wins).filter(([id])=>!['editor','preview'].includes(id)).map(([id,w])=>({id,minimized:w.style.display==='none'})))}
function fsChanged(){stats();if(wins.files)renderFiles();if(wins.trash)renderFiles(true);if(wins.settings&&settingsSection==='storage')renderSettings();renderDesktopDisks()}
stats=function(){if(!fsReady)return;$('#file-count').textContent=VFS.model.all().filter(n=>n.kind==='file'&&!n.deleted).length;$('.storage-widget .widget-caption').textContent=sizeLabel(VFS.bytes())+' · IndexedDB'};
function renderDesktopDisks(){const area=$('.desktop-files');area.innerHTML=VFS.model.all().filter(n=>n.kind==='disk').map(n=>`<button data-disk="${n.id}"><span class="disk-icon">◉</span>${esc(n.name)}</button>`).join('')+'<button data-desktop-notes><span class="paper-icon">≡</span>Заметки</button>';$$('[data-disk]',area).forEach(b=>b.onclick=()=>navigateFiles(b.dataset.disk));$('[data-desktop-notes]',area).onclick=()=>openApp('notes')}
function navigateFiles(id,history=true){if(!fsReady){toast('Файловая система загружается');return}if(id!==null)VFS.model.folder(id);if(history&&fileLocation!==id){fileBack.push(fileLocation);fileForward=[]}fileLocation=id;fileSelection.clear();fileQuery='';if(wins.files){focusWin('files');renderFiles()}else openApp('files')}
function breadcrumbs(){if(!fileLocation)return '<button data-path="">Этот компьютер</button>';const chain=[];let n=VFS.model.get(fileLocation);while(n){chain.unshift(n);n=VFS.model.nodes.get(n.parent)}return '<button data-path="">Компьютер</button>'+chain.map(n=>`<span>›</span><button data-path="${n.id}">${esc(n.name)}</button>`).join('')}
function renderFiles(trash=false){const id=trash?'trash':'files',root=body(id);if(!fsReady){root.innerHTML='<div class="empty">'+esc(fsFailure||'Подготовка файловой системы…')+'</div>';return}if(fileLocation&&(!VFS.model.nodes.has(fileLocation)||VFS.model.get(fileLocation).deleted))fileLocation=null;
  const disks=VFS.model.all().filter(n=>n.kind==='disk');let list=trash?VFS.model.all().filter(n=>n.deleted&&n.trashRoot===n.id):fileLocation?VFS.model.children(fileLocation):disks;
  list=list.filter(n=>n.name.toLowerCase().includes(fileQuery.toLowerCase())).sort((a,b)=>{if(a.kind!==b.kind)return a.kind==='file'?1:-1;if(fileSort==='size')return (b.size||0)-(a.size||0);if(fileSort==='date')return b.modified-a.modified;return a.name.localeCompare(b.name,'ru')});
  root.innerHTML=`<div class="split file-shell"><aside class="sidebar"><small>ИЗБРАННОЕ</small><button data-nav="" class="${!fileLocation&&!trash?'selected':''}">▦ &nbsp; Компьютер</button>${['Рабочий стол','Документы','Изображения','Музыка','Загрузки'].map(name=>`<button data-nav="${quickFolder(name)}" class="${fileLocation===quickFolder(name)&&!trash?'selected':''}">▱ &nbsp; ${name}</button>`).join('')}<small style="margin-top:25px">ВИРТУАЛЬНЫЕ ДИСКИ</small>${disks.map(d=>`<button data-nav="${d.id}" class="${fileLocation===d.id&&!trash?'selected':''}">◉ &nbsp; ${esc(d.name)}</button>`).join('')}<button data-trash class="${trash?'selected':''}">♲ &nbsp; Корзина</button><button data-storage>⚙ &nbsp; Управление дисками</button></aside><div class="content file-content"><div class="toolbar file-toolbar">${trash?'<button data-empty-trash>Очистить корзину</button>':`<button data-back title="Назад" ${fileBack.length?'':'disabled'}>‹</button><button data-forward title="Вперёд" ${fileForward.length?'':'disabled'}>›</button><button data-up title="На уровень вверх" ${fileLocation?'':'disabled'}>↑</button><button data-new-folder ${fileLocation?'':'disabled'}>+ Папка</button><button data-new-text ${fileLocation?'':'disabled'}>+ Файл</button><button data-import ${fileLocation?'':'disabled'}>Импорт</button><button data-paste ${clipboard&&fileLocation?'':'disabled'}>Вставить</button>`}<button data-view title="Переключить вид">${fileView==='grid'?'☷':'▦'}</button></div><div class="file-path">${trash?'Корзина':breadcrumbs()}<input data-file-search aria-label="Поиск в папке" placeholder="Поиск в папке" value="${esc(fileQuery)}"></div><div class="file-actionbar"><span>${fileSelection.size?'Выбрано: '+fileSelection.size:'Выберите файл · двойной клик — открыть'}</span><button data-selection-actions ${fileSelection.size?'':'disabled'}>Действия ▾</button><select data-sort aria-label="Сортировка"><option value="name" ${fileSort==='name'?'selected':''}>По имени</option><option value="date" ${fileSort==='date'?'selected':''}>По дате</option><option value="size" ${fileSort==='size'?'selected':''}>По размеру</option></select></div><div class="fs-items ${fileView==='list'?'list-view':''}" tabindex="0" aria-label="Список файлов">${list.map(n=>`<button class="fs-item ${fileSelection.has(n.id)?'selected':''}" data-node="${n.id}" draggable="${!trash&&n.kind!=='disk'}" aria-label="${esc(n.name)}" aria-pressed="${fileSelection.has(n.id)}"><span class="fs-glyph ${n.kind}">${glyph(n)}</span><span class="fs-name">${esc(n.name)}</span><span class="fs-type">${n.kind==='disk'?'Виртуальный диск':n.kind==='folder'?'Папка':n.type||'Файл'}</span><span class="fs-size">${n.kind==='file'?sizeLabel(n.size):sizeLabel(VFS.bytes(n.id))}</span><span class="fs-date">${new Date(n.modified).toLocaleDateString('ru-RU')}</span></button>`).join('')||`<div class="empty">${fileQuery?'Ничего не найдено':'Здесь пока пусто'}<br>${trash?'Удалённые файлы появятся здесь.':fileLocation?'Перетащите файлы с компьютера или создайте папку.':'Создайте виртуальный диск в настройках.'}</div>`}</div><div class="status">${list.length} объектов · ${fileLocation?'Перетащите файлы сюда для импорта':'Виртуальные диски используют общее хранилище браузера'}</div></div></div>`;
  const items=$('.fs-items',root);
  $$('[data-nav]',root).forEach(b=>b.onclick=act(()=>navigateFiles(b.dataset.nav||null)));$('[data-trash]',root).onclick=()=>{fileSelection.clear();openApp('trash')};$('[data-storage]',root).onclick=()=>{settingsSection='storage';openApp('settings');renderSettings()};
  $$('[data-path]',root).forEach(b=>b.onclick=act(()=>navigateFiles(b.dataset.path||null)));
  $$('[data-node]',root).forEach(b=>{const n=VFS.model.get(b.dataset.node);b.onclick=e=>{if(!e.ctrlKey&&!e.metaKey)fileSelection.clear();if(fileSelection.has(n.id))fileSelection.delete(n.id);else fileSelection.add(n.id);$$('[data-node]',root).forEach(el=>{el.classList.toggle('selected',fileSelection.has(el.dataset.node));el.setAttribute('aria-pressed',String(fileSelection.has(el.dataset.node)))});$('.file-actionbar>span',root).textContent='Выбрано: '+fileSelection.size;$('[data-selection-actions]',root).disabled=!fileSelection.size};b.ondblclick=act(()=>trash?restoreNode(n.id):n.kind==='file'?openFile(n):navigateFiles(n.id));b.oncontextmenu=e=>{e.preventDefault();if(!fileSelection.has(n.id)){fileSelection.clear();fileSelection.add(n.id)}nodeMenu(n,trash)};b.ondragstart=e=>{e.dataTransfer.setData('application/x-forma-node',n.id);e.dataTransfer.effectAllowed='move'};if(!trash&&n.kind!=='file'){b.ondragover=e=>{e.preventDefault();b.classList.add('drop-target')};b.ondragleave=()=>b.classList.remove('drop-target');b.ondrop=act(async e=>{e.preventDefault();e.stopPropagation();b.classList.remove('drop-target');await dropFiles(e,n.id)})}});
  $('[data-file-search]',root).oninput=e=>{const pos=e.target.selectionStart;fileQuery=e.target.value;renderFiles(trash);const el=$('[data-file-search]',root);el.focus();el.setSelectionRange(pos,pos)};$('[data-sort]',root).onchange=e=>{fileSort=e.target.value;renderFiles(trash)};$('[data-view]',root).onclick=()=>{fileView=fileView==='grid'?'list':'grid';save('file-view',fileView);renderFiles(trash)};
  $('[data-selection-actions]',root).onclick=()=>{const n=VFS.model.nodes.get([...fileSelection][0]);if(n)nodeMenu(n,trash)};
  if(trash){$('[data-empty-trash]',root).onclick=()=>confirmDialog('Очистить корзину?','Все объекты в корзине будут удалены без возможности восстановления.',act(async()=>{await VFS.mutate(m=>{for(const n of m.all())if(n.deleted)m.nodes.delete(n.id)});fileSelection.clear()}))}else{
    $('[data-back]',root).onclick=()=>{fileForward.push(fileLocation);navigateFiles(fileBack.pop(),false)};$('[data-forward]',root).onclick=()=>{fileBack.push(fileLocation);navigateFiles(fileForward.pop(),false)};$('[data-up]',root).onclick=()=>navigateFiles(VFS.model.get(fileLocation).parent);
    $('[data-new-folder]',root).onclick=()=>newNode('folder');$('[data-new-text]',root).onclick=()=>newNode('file');$('[data-import]',root).onclick=()=>{const destination=fileLocation;const input=document.createElement('input');input.type='file';input.multiple=true;input.onchange=act(async()=>{const count=await VFS.import(input.files,destination);toast('Импортировано файлов: '+count)});input.click()};$('[data-paste]',root).onclick=act(pasteFiles);
    items.ondragover=e=>{if(fileLocation){e.preventDefault();items.classList.add('drop-zone')}};items.ondragleave=()=>items.classList.remove('drop-zone');items.ondrop=act(async e=>{e.preventDefault();items.classList.remove('drop-zone');if(fileLocation)await dropFiles(e,fileLocation)});
  }
  items.onkeydown=act(async e=>{if(e.key==='Enter'&&fileSelection.size===1){const n=VFS.model.get([...fileSelection][0]);if(trash)await restoreNode(n.id);else if(n.kind==='file')openFile(n);else navigateFiles(n.id)}if(e.key==='Delete'&&!trash){e.preventDefault();await trashSelected()}if((e.ctrlKey||e.metaKey)&&['c','x','v','a'].includes(e.key.toLowerCase())){e.preventDefault();const k=e.key.toLowerCase();if(k==='a'){fileSelection=new Set(list.map(n=>n.id));renderFiles(trash)}if(k==='c'||k==='x'){clipboard={ids:[...fileSelection],cut:k==='x'};toast(k==='x'?'Выбрано для перемещения':'Скопировано');renderFiles(trash)}if(k==='v'&&!trash&&fileLocation)await pasteFiles()}});
}
async function dropFiles(e,parent){const id=e.dataTransfer.getData('application/x-forma-node');if(id)await VFS.mutate(m=>m.move(id,parent));else if(e.dataTransfer.files.length){const count=await VFS.import(e.dataTransfer.files,parent);toast('Импортировано: '+count)}}
function newNode(kind){const parent=fileLocation;inputDialog(kind==='folder'?'Новая папка':'Новый текстовый файл',kind==='folder'?'Новая папка':'Документ.txt',act(async name=>{const n=await VFS.mutate(m=>m.create(parent,name,kind));if(kind==='file')openFile(n)}))}
async function pasteFiles(){if(!clipboard||!fileLocation)return;const current={...clipboard};await VFS.mutate(m=>{for(const id of current.ids){if(current.cut)m.move(id,fileLocation);else m.copy(id,fileLocation)}});if(current.cut)clipboard=null;fileSelection.clear();renderFiles();toast(current.cut?'Перемещено':'Скопировано')}
async function trashSelected(){const ids=[...fileSelection];await VFS.mutate(m=>{for(const id of ids){const n=m.nodes.get(id);if(n&&!n.deleted)m.trash(id)}});fileSelection.clear()}
async function restoreNode(id){await VFS.mutate(m=>m.restore(id));fileSelection.clear();toast('Объект восстановлен')}
function nodeMenu(n,trash){const panel=showPanel(`<h3>${fileSelection.size>1?'Выбрано объектов: '+fileSelection.size:esc(n.name)}</h3>${trash?'<button data-do="restore">Восстановить</button><button data-do="purge">Удалить навсегда</button>':`<button data-do="open">Открыть</button><button data-do="rename">Переименовать</button>${n.kind!=='disk'?'<button data-do="copy">Копировать</button><button data-do="cut">Вырезать</button><button data-do="move">Переместить в…</button><button data-do="trash">В корзину</button>':''}${n.kind==='file'?'<button data-do="download">Скачать</button>':''}<button data-do="info">Свойства</button>`}`);
  $$('[data-do]',panel).forEach(b=>b.onclick=act(async()=>{const action=b.dataset.do;closeOverlay();if(action==='open'){if(n.kind==='file')openFile(n);else navigateFiles(n.id)}if(action==='rename')inputDialog('Переименовать',n.name,act(name=>VFS.mutate(m=>m.rename(n.id,name))));if(['copy','cut'].includes(action)){clipboard={ids:fileSelection.size?[...fileSelection]:[n.id],cut:action==='cut'};toast(action==='cut'?'Выбрано для перемещения':'Скопировано');if(wins.files)renderFiles()}if(action==='move')chooseDestination(n);if(action==='trash')await trashSelected();if(action==='restore'){const ids=fileSelection.size?[...fileSelection]:[n.id];await VFS.mutate(m=>ids.forEach(id=>m.restore(id)));fileSelection.clear()}if(action==='purge'){const ids=fileSelection.size?[...fileSelection]:[n.id];confirmDialog('Удалить навсегда?','Восстановление будет невозможно.',act(()=>VFS.mutate(m=>ids.forEach(id=>{if(m.nodes.has(id))m.purge(id)}))))}if(action==='download')downloadFile(n);if(action==='info')showPanel(`<h3>${esc(n.name)}</h3><dl class="properties"><dt>Тип</dt><dd>${esc(n.kind==='disk'?'Виртуальный диск':n.kind==='folder'?'Папка':n.type)}</dd><dt>Путь</dt><dd>${esc(VFS.model.path(n.id))}</dd><dt>Размер</dt><dd>${sizeLabel(VFS.bytes(n.id))}</dd><dt>Изменён</dt><dd>${new Date(n.modified).toLocaleString('ru-RU')}</dd><dt>Хранилище</dt><dd>IndexedDB, этот браузер</dd></dl>`)}))}
function chooseDestination(n){const ids=fileSelection.size?[...fileSelection]:[n.id];const excluded=new Set(ids.flatMap(id=>[...VFS.model.descendants(id)]));const folders=VFS.model.all().filter(x=>!x.deleted&&x.kind!=='file'&&!excluded.has(x.id));const panel=showPanel('<h3>Переместить в папку</h3><div class="destination-list">'+folders.map(f=>`<button data-dest="${f.id}">${esc(VFS.model.path(f.id))}</button>`).join('')+'</div>');$$('[data-dest]',panel).forEach(b=>b.onclick=act(async()=>{await VFS.mutate(m=>ids.forEach(id=>m.move(id,b.dataset.dest)));closeOverlay();fileSelection.clear();toast('Перемещено')}))}
function downloadFile(n){const url=URL.createObjectURL(n.blob);const a=document.createElement('a');a.href=url;a.download=n.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function openFile(n){if(n.kind!=='file')return navigateFiles(n.id);const text=n.type?.startsWith('text/')||/\.(txt|md|json|csv|js|css|html|xml|log|yaml|yml)$/i.test(n.name);if(text){if(editorDirty){confirmDialog('Открыть другой файл?','Несохранённые изменения текущего файла будут потеряны.',()=>{editorDirty=false;openFile(n)});return}editorFile=n.id;openApp('editor');renderEditor()}else{previewFile=n.id;openApp('preview');renderPreview()}}
async function renderEditor(){const root=body('editor'),id=editorFile;if(!id){root.innerHTML='<div class="empty">Откройте текстовый файл из файлового менеджера.</div>';return}const n=VFS.model.nodes.get(id);if(!n||n.deleted){root.innerHTML='<div class="empty">Файл удалён или перемещён в корзину.</div>';return}if(n.size>8*1024*1024){root.innerHTML='<div class="empty">Для редактора доступны текстовые файлы до 8 МБ.<br>Более крупные файлы можно скачать.</div>';return}root.innerHTML='<div class="empty">Чтение файла…</div>';const text=await n.blob.text();if(!root.isConnected||editorFile!==id)return;root.innerHTML=`<div class="text-editor"><div class="toolbar"><span class="editor-name">${esc(n.name)}</span><button data-save-text>Сохранить</button><button data-save-as>Сохранить как…</button></div><textarea spellcheck="false" aria-label="Текст файла">${esc(text)}</textarea><div class="status" data-editor-status>UTF-8 · ${sizeLabel(n.size)} · Сохранено</div></div>`;editorDirty=false;const area=$('textarea',root);area.oninput=()=>{editorDirty=true;$('[data-editor-status]',root).textContent='Есть несохранённые изменения · '+area.value.length+' символов'};const saveText=act(async()=>{await VFS.mutate(m=>m.write(id,new Blob([area.value],{type:n.type||'text/plain'})));editorDirty=false;$('[data-editor-status]',root).textContent='Сохранено · '+new Date().toLocaleTimeString('ru-RU')});$('[data-save-text]',root).onclick=saveText;area.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveText()}};$('[data-save-as]',root).onclick=()=>inputDialog('Сохранить копию',n.name,act(async name=>{const created=await VFS.mutate(m=>m.create(n.parent,m.unique(n.parent,name),'file',new Blob([area.value],{type:n.type})));editorFile=created.id;editorDirty=false;renderEditor()}))}
function renderPreview(){const root=body('preview');for(const url of windowResources.get('preview')||[])URL.revokeObjectURL(url);windowResources.set('preview',[]);const n=VFS.model.nodes.get(previewFile);if(!n){root.innerHTML='<div class="empty">Откройте изображение, видео, аудио или PDF из Файлов.</div>';return}const url=ownUrl('preview',n.blob);let html='<div class="empty">Встроенный просмотр этого формата недоступен.</div>';if(n.type.startsWith('image/'))html=`<img src="${url}" alt="${esc(n.name)}">`;else if(n.type.startsWith('video/'))html=`<video controls src="${url}"></video>`;else if(n.type.startsWith('audio/'))html=`<div class="media-cover">♫<audio controls src="${url}"></audio></div>`;else if(n.type==='application/pdf')html=`<iframe src="${url}" title="PDF: ${esc(n.name)}"></iframe>`;root.innerHTML=`<div class="preview-shell"><div class="toolbar"><span>${esc(n.name)}</span><button data-download>Скачать</button></div><div class="preview-stage">${html}</div></div>`;$('[data-download]',root).onclick=()=>downloadFile(n)}

let browserTabs=[],activeBrowserTab=null;
const savedBookmarks=read('browser-bookmarks',[{name:'Wikipedia',url:'https://www.wikipedia.org'},{name:'GitHub',url:'https://github.com'},{name:'Яндекс',url:'https://ya.ru'}]);
function safeAddress(raw){const q=raw.trim();if(!q)return 'about:home';let candidate=q;if(!/^https?:\/\//i.test(q)){if(/^[\w.-]+\.[a-z]{2,}([/:?#].*)?$/i.test(q))candidate='https://'+q;else return 'https://www.google.com/search?q='+encodeURIComponent(q)}const url=new URL(candidate);if(url.protocol!=='https:'&&url.protocol!=='http:')throw Error('Доступны только HTTP и HTTPS');return url.href}
function currentTab(){return browserTabs.find(t=>t.id===activeBrowserTab)}
function addBrowserTab(url='about:home'){const tab={id:crypto.randomUUID(),url:'about:home',history:['about:home'],index:0,frame:null};browserTabs.push(tab);activeBrowserTab=tab.id;if(url!=='about:home')goBrowser(url);else renderBrowser()}
function goBrowser(raw,history=true){const tab=currentTab();if(!tab)return;const url=raw==='about:home'?raw:safeAddress(raw);if(history){tab.history=tab.history.slice(0,tab.index+1);tab.history.push(url);tab.index=tab.history.length-1}tab.url=url;if(tab.frame){tab.frame.remove();tab.frame=null}renderBrowser();if(url!=='about:home'){const log=read('browser-history',[]);log.unshift({url,date:Date.now()});save('browser-history',log.slice(0,100))}}
function renderBrowser(){const root=body('browser');if(!browserTabs.length){addBrowserTab();return}const tab=currentTab();const markup=`<div class="browser-shell"><div class="browser-tabs">${browserTabs.map(t=>`<div class="browser-tab ${t.id===tab.id?'active':''}"><button data-tab="${t.id}">${t.url==='about:home'?'Новая вкладка':esc(new URL(t.url).hostname)}</button><button data-close-tab="${t.id}" aria-label="Закрыть вкладку">×</button></div>`).join('')}<button data-add-tab aria-label="Новая вкладка">+</button></div><form class="browser-address"><button type="button" data-browser-back title="Назад" ${tab.index?'':'disabled'}>‹</button><button type="button" data-browser-forward title="Вперёд" ${tab.index<tab.history.length-1?'':'disabled'}>›</button><button type="button" data-browser-reload title="Обновить">↻</button><button type="button" data-browser-home title="Домой">⌂</button><input aria-label="Адрес сайта или поиск" value="${tab.url==='about:home'?'':esc(tab.url)}" placeholder="Введите адрес или поисковый запрос"><button title="Перейти">→</button><button type="button" data-bookmark title="Добавить закладку">☆</button><button type="button" data-browser-history title="История">◷</button></form><div class="browser-bookmarks">${savedBookmarks.map((b,i)=>`<button data-bookmark-open="${i}">${esc(b.name)}</button>`).join('')}</div><div class="browser-content">${tab.url==='about:home'?`<div class="browser-start"><span class="eyebrow">FORMA BROWSER</span><h2>Начните с любопытства.</h2><p>Откройте сайт, который вам интересен.</p><div class="start-bookmarks">${savedBookmarks.map((b,i)=>`<button data-bookmark-open="${i}"><span>↗</span>${esc(b.name)}</button>`).join('')}</div><p class="browser-explanation">Сайты открываются внутри Forma, если разрешают встраивание.<br>Для остальных используйте кнопку «Открыть снаружи».</p></div>`:''}</div>${tab.url!=='about:home'?'<div class="browser-notice"><span>Пустая страница или отказ? Сайт может запрещать встраивание. Его внутренние переходы не видны Forma.</span><button data-open-external>Открыть снаружи ↗</button></div>':''}</div>`;
  if(!$('.browser-shell',root))root.innerHTML=markup;else{const temp=document.createElement('div');temp.innerHTML=markup;for(const selector of ['.browser-tabs','.browser-address','.browser-bookmarks'])$(selector,root).replaceWith($(selector,temp));$('.browser-notice',root)?.remove();const notice=$('.browser-notice',temp);if(notice)$('.browser-shell',root).append(notice);$('.browser-start',root)?.remove();const start=$('.browser-start',temp);if(start)$('.browser-content',root).append(start)}
  const area=$('.browser-content',root);for(const t of browserTabs){if(t.url==='about:home')continue;if(!t.frame){t.frame=document.createElement('iframe');t.frame.title='Сайт: '+new URL(t.url).hostname;t.frame.setAttribute('sandbox','allow-scripts allow-forms allow-same-origin allow-popups allow-popups-to-escape-sandbox allow-downloads');t.frame.referrerPolicy='strict-origin-when-cross-origin';t.frame.src=t.url}t.frame.style.display=t.id===tab.id?'block':'none';if(t.frame.parentNode!==area)area.append(t.frame)}
  $$('[data-tab]',root).forEach(b=>b.onclick=()=>{activeBrowserTab=b.dataset.tab;renderBrowser()});$$('[data-close-tab]',root).forEach(b=>b.onclick=()=>{const t=browserTabs.find(t=>t.id===b.dataset.closeTab);t.frame?.remove();browserTabs=browserTabs.filter(x=>x.id!==t.id);if(activeBrowserTab===t.id)activeBrowserTab=browserTabs[0]?.id;renderBrowser()});$('[data-add-tab]',root).onclick=()=>addBrowserTab();$('form',root).onsubmit=act(e=>{e.preventDefault();goBrowser($('input',root).value)});$('[data-browser-back]',root).onclick=()=>{tab.index--;goBrowser(tab.history[tab.index],false)};$('[data-browser-forward]',root).onclick=()=>{tab.index++;goBrowser(tab.history[tab.index],false)};$('[data-browser-reload]',root).onclick=()=>goBrowser(tab.url,false);$('[data-browser-home]',root).onclick=()=>goBrowser('about:home');$$('[data-bookmark-open]',root).forEach(b=>b.onclick=act(()=>goBrowser(savedBookmarks[+b.dataset.bookmarkOpen].url)));$('[data-bookmark]',root).onclick=()=>{if(tab.url==='about:home')return toast('Сначала откройте сайт');inputDialog('Добавить закладку',new URL(tab.url).hostname,name=>{savedBookmarks.push({name,url:tab.url});save('browser-bookmarks',savedBookmarks);renderBrowser()})};$('[data-browser-history]',root).onclick=()=>{const history=read('browser-history',[]),panel=showPanel('<h3>История адресов</h3><button data-clear-history>Очистить историю</button><div class="destination-list">'+history.map((h,i)=>`<button data-history-item="${i}">${esc(h.url)}<small>${new Date(h.date).toLocaleString('ru-RU')}</small></button>`).join('')+'</div>');$$('[data-history-item]',panel).forEach(b=>b.onclick=act(()=>{goBrowser(history[+b.dataset.historyItem].url);closeOverlay()}));$('[data-clear-history]',panel).onclick=()=>{save('browser-history',[]);closeOverlay();toast('История очищена')}};if($('[data-open-external]',root))$('[data-open-external]',root).onclick=()=>window.open(tab.url,'_blank','noopener,noreferrer');
}
function renderTasks(){const root=body('tasks');root.innerHTML=`<div class="task-manager"><div class="section-heading"><div><span class="eyebrow">FORMA SYSTEM</span><h2>Диспетчер приложений</h2></div><button class="soft-button" data-refresh-tasks>Обновить</button></div><div class="system-metrics"><div><small>Открытые приложения</small><strong>${Object.keys(wins).length}</strong></div><div><small>Время работы среды</small><strong>${Math.floor((Date.now()-systemStarted)/60000)} мин</strong></div><div><small>Файлы в хранилище</small><strong>${sizeLabel(VFS.bytes())}</strong></div></div><table class="process-table"><thead><tr><th>Приложение</th><th>Состояние</th><th>Время</th><th>Действия</th></tr></thead><tbody>${Object.entries(wins).map(([id,w])=>`<tr><td><span class="process-icon">${apps[id].icon}</span>${esc(apps[id].name)}</td><td><span class="process-state ${w.style.display==='none'?'minimized':''}">${w.style.display==='none'?'Свёрнуто':'Открыто'}</span>${id==='browser'?' · '+browserTabs.length+' вкладок':''}</td><td>${Math.floor((Date.now()-(processes.get(id)?.started||Date.now()))/1000)} с</td><td><button data-process-open="${id}">Показать</button><button data-process-close="${id}" ${id==='tasks'?'disabled':''}>Завершить</button></td></tr>`).join('')}</tbody></table><div class="system-explanation"><b>Область контроля — приложения Forma</b><p>Свёрнутые окна могут продолжать воспроизведение аудио. «Завершить» закрывает приложение и освобождает его ресурсы; редактор предупредит о несохранённом тексте.</p><p>Браузер не предоставляет надёжные CPU и RAM для каждого внутреннего окна. Системные процессы вашего компьютера здесь недоступны.</p><span data-memory></span></div></div>`;$$('[data-process-open]',root).forEach(b=>b.onclick=()=>openApp(b.dataset.processOpen));$$('[data-process-close]',root).forEach(b=>b.onclick=()=>{closeApp(b.dataset.processClose);if(wins.tasks)renderTasks()});$('[data-refresh-tasks]',root).onclick=renderTasks;if(performance.memory)$('[data-memory]',root).textContent='JS-куча страницы (оценка браузера): '+sizeLabel(performance.memory.usedJSHeapSize)}
setInterval(()=>{if(wins.tasks&&wins.tasks.style.display!=='none'&&!document.hidden)renderTasks()},2000);
function renderSettings(){const root=body('settings');const tabs={appearance:'Оформление',storage:'Диски и память',behavior:'Рабочая среда',backup:'Резервная копия',system:'О системе'};root.innerHTML=`<div class="split"><aside class="sidebar"><small>НАСТРОЙКИ</small>${Object.entries(tabs).map(([id,name])=>`<button data-settings-section="${id}" class="${id===settingsSection?'selected':''}">${name}</button>`).join('')}</aside><div class="content"><div class="settings system-settings"><span class="eyebrow">FORMA PREFERENCES</span><h2>${tabs[settingsSection]}</h2><div data-settings-content></div></div></div></div>`;$$('[data-settings-section]',root).forEach(b=>b.onclick=()=>{settingsSection=b.dataset.settingsSection;renderSettings()});const target=$('[data-settings-content]',root);
  if(settingsSection==='appearance'){target.innerHTML=`<div class="setting-row"><span>Ваше имя<small>Приветствие на рабочем столе</small></span><input type="text" id="user-name" maxlength="24" value="${esc(settings.name)}" aria-label="Ваше имя"></div><div class="setting-row"><span>Тёмная тема</span><input id="dark-mode" type="checkbox" class="switch" ${settings.dark?'checked':''}></div><div class="setting-row"><span>Обои</span><div class="wall-options">${['#c8cac3','#adbe97','#d1b6a9'].map((c,i)=>`<button class="wall-option ${settings.wall===i?'chosen':''}" data-wall="${i}" style="background:${c}" aria-label="Обои ${i+1}"></button>`).join('')}</div></div><div class="setting-row"><span>Меньше анимации<small>Также учитывается настройка устройства</small></span><input data-motion type="checkbox" class="switch" ${settings.reduceMotion?'checked':''}></div><div class="setting-row"><span>Размер текста</span><select data-text-size><option value="13">Обычный</option><option value="15">Крупный</option></select></div>`;$('#user-name',root).oninput=e=>{settings.name=e.target.value;applySettings()};$('#dark-mode',root).onchange=e=>{settings.dark=e.target.checked;applySettings()};$$('[data-wall]',root).forEach(b=>b.onclick=()=>{settings.wall=+b.dataset.wall;applySettings();renderSettings()});$('[data-motion]',root).onchange=e=>{settings.reduceMotion=e.target.checked;applySystemSettings()};$('[data-text-size]',root).value=String(settings.fontSize||13);$('[data-text-size]',root).onchange=e=>{settings.fontSize=+e.target.value;applySystemSettings()}}
  if(settingsSection==='storage'){if(!fsReady){target.innerHTML='<p>'+esc(fsFailure||'Загрузка…')+'</p>';return}const disks=VFS.model.all().filter(n=>n.kind==='disk');target.innerHTML=`<p class="muted">Виртуальные диски разделяют хранилище этого сайта. Это не физические разделы компьютера.</p><div class="storage-summary" data-storage-estimate>Определяем доступный объём…</div><div class="disk-list">${disks.map(n=>`<article class="disk-card"><span class="disk-icon">◉</span><div><b>${esc(n.name)}</b><small>${n.system?'Системный диск':'Пользовательский диск'} · ${sizeLabel(VFS.bytes(n.id))}</small></div><button data-open-disk="${n.id}">Открыть</button><button data-disk-options="${n.id}" aria-label="Действия с диском ${esc(n.name)}">•••</button></article>`).join('')}</div><button class="soft-button" data-add-disk>+ Создать виртуальный диск</button><div class="setting-row"><span>Защита от автоматической очистки<small data-persistence-state>Проверка…</small></span><button class="soft-button" data-persist>Запросить</button></div><p class="muted">Импорт ограничен доступным местом браузера. Очистка данных сайта удаляет диски. Сохраняйте резервные копии.</p>`;navigator.storage?.estimate().then(s=>{if(target.isConnected)$('[data-storage-estimate]',target).textContent='Занято сайтом: '+sizeLabel(s.usage)+' · квота браузера: '+sizeLabel(s.quota)}).catch(()=>{});navigator.storage?.persisted?.().then(v=>{if(target.isConnected)$('[data-persistence-state]',target).textContent=v?'Постоянное хранение разрешено':'Решение принимает браузер'});$('[data-persist]',target).onclick=act(async()=>{if(!navigator.storage?.persist)return toast('Браузер не поддерживает запрос');const yes=await navigator.storage.persist();toast(yes?'Постоянное хранение разрешено':'Браузер не предоставил постоянное хранение');renderSettings()});$('[data-add-disk]',target).onclick=()=>inputDialog('Название нового диска','Архив',act(name=>VFS.mutate(m=>m.create(null,name,'disk'))));$$('[data-open-disk]',target).forEach(b=>b.onclick=()=>navigateFiles(b.dataset.openDisk));$$('[data-disk-options]',target).forEach(b=>b.onclick=()=>diskMenu(b.dataset.diskOptions))}
  if(settingsSection==='behavior'){target.innerHTML=`<div class="setting-row"><span>Концентрация<small>Приглушить второстепенные виджеты</small></span><input data-setting="focus" type="checkbox" class="switch" ${settings.focus?'checked':''}></div><div class="setting-row"><span>Восстановление сеанса<small>Открывать приложения после перезагрузки</small></span><input data-setting="restoreSession" type="checkbox" class="switch" ${settings.restoreSession?'checked':''}></div><div class="setting-row"><span>Показывать виджеты</span><input data-setting="widgets" type="checkbox" class="switch" ${settings.widgets!==false?'checked':''}></div><div class="setting-row"><span>Экран паузы<small>Скрывает рабочий стол. Это не парольная защита.</small></span><button class="soft-button" data-lock>Включить</button></div><h3>Сочетания клавиш</h3><div class="shortcuts"><p><kbd>Ctrl / ⌘ + K</kbd> Поиск приложений</p><p><kbd>Ctrl + Shift + Esc</kbd> Диспетчер Forma</p><p><kbd>Ctrl / ⌘ + S</kbd> Сохранить в редакторе</p><p><kbd>Ctrl / ⌘ + C / X / V</kbd> Копирование / перенос в Файлах</p><p><kbd>Delete</kbd> В корзину · <kbd>Enter</kbd> Открыть</p></div>`;$$('[data-setting]',target).forEach(input=>input.onchange=()=>{settings[input.dataset.setting]=input.checked;applySystemSettings()});$('[data-lock]',target).onclick=lockScreen}
  if(settingsSection==='backup'){target.innerHTML='<p class="muted">Одна копия содержит диски, файлы, заметки, календарь, быстрые записи, закладки и настройки.</p><div class="setting-row"><span>Экспортировать данные<small>Формат Forma JSON, включая содержимое файлов</small></span><button class="soft-button" data-export-backup>Скачать</button></div><div class="setting-row"><span>Восстановить данные<small>Текущие данные заменяются после подтверждения</small></span><button class="soft-button" data-import-backup>Выбрать</button><input data-backup-file type="file" accept=".json" hidden></div><p class="muted">Для крупных коллекций скачивайте отдельные файлы. Полная копия собирается в памяти; экспорт ограничен 100 МБ исходных файлов.</p><div data-backup-status class="muted" role="status"></div>';$('[data-export-backup]',target).onclick=act(async()=>{const b=$('[data-export-backup]',target);b.disabled=true;try{$('[data-backup-status]',target).textContent='Собираем копию…';await exportBackup();$('[data-backup-status]',target).textContent='Копия передана браузеру для скачивания.'}finally{b.disabled=false}});$('[data-import-backup]',target).onclick=()=>$('[data-backup-file]',target).click();$('[data-backup-file]',target).onchange=act(async e=>{const f=e.target.files[0];if(!f)return;if(f.size>150*1024*1024)throw Error('Копия слишком велика: максимум 150 МБ');const payload=JSON.parse(await f.text());const parsed=await validateBackup(payload);confirmDialog('Заменить все данные Forma?','Текущие диски, файлы, заметки и настройки будут заменены. Сначала сохраните свою резервную копию.',act(async()=>{await VFS.mutate(m=>{m.nodes=parsed.nodes});notes=payload.notes;events=payload.events;settings=payload.settings;save('notes',notes);save('events',events);save('settings',settings);save('quick',payload.quick||'');save('browser-bookmarks',payload.bookmarks||[]);location.reload()}))})}
  if(settingsSection==='system'){target.innerHTML=`<div class="about system-about"><div class="logo">✺</div><h2>Forma OS <small>2.0</small></h2><p>Ваше пространство. В вашем браузере.</p></div><div class="setting-row"><span>Файловая система</span><b>IndexedDB</b></div><div class="setting-row"><span>Сеть</span><b>${navigator.onLine?'Подключение доступно':'Офлайн'}</b></div><div class="setting-row"><span>Открытые приложения</span><button class="soft-button" data-open-tasks>${Object.keys(wins).length} · Диспетчер</button></div><p class="muted">Веб-среда не запускает EXE, APK или приложения macOS. Терминал работает с виртуальными дисками Forma. Встроенный браузер подчиняется правилам безопасности сайтов. Системные настройки устройства не изменяются.</p>`;$('[data-open-tasks]',target).onclick=()=>openApp('tasks')}
}
function diskMenu(id){const n=VFS.model.get(id),p=showPanel(`<h3>${esc(n.name)}</h3><button data-disk-rename>Переименовать</button><button data-disk-format>Очистить диск…</button>${!n.system?'<button data-disk-remove>Удалить пустой диск</button>':''}`);$('[data-disk-rename]',p).onclick=()=>inputDialog('Название диска',n.name,act(name=>VFS.mutate(m=>m.rename(id,name))));$('[data-disk-format]',p).onclick=()=>confirmDialog('Очистить диск «'+n.name+'»?','Все папки и файлы на этом виртуальном диске, включая корзину, будут удалены навсегда. Другие диски не изменятся.',act(()=>VFS.mutate(m=>m.format(id))));if($('[data-disk-remove]',p))$('[data-disk-remove]',p).onclick=act(async()=>{await VFS.mutate(m=>m.removeDisk(id));closeOverlay()})}
function blobData(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)})}
async function exportBackup(){if(!fsReady)throw Error('Хранилище не готово');if(VFS.bytes()>100*1024*1024)throw Error('Полная копия ограничена 100 МБ. Скачайте крупные файлы отдельно.');const nodes=[];for(const n of VFS.model.all()){const {blob,...meta}=n;nodes.push({...meta,...(blob?{data:await blobData(blob)}:{})})}download('forma-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({version:2,nodes,notes,events,settings,quick:$('#quick-note').value,bookmarks:savedBookmarks}),'application/json')}
async function validateBackup(data){if(data.version!==2||!Array.isArray(data.nodes)||!Array.isArray(data.notes)||!data.notes.every(n=>typeof n.id==='string'&&/^[-a-zA-Z0-9_]+$/.test(n.id)&&typeof n.title==='string'&&typeof n.text==='string')||!data.events||typeof data.events!=='object'||!data.settings||typeof data.settings!=='object')throw Error('Некорректная резервная копия Forma 2.0');if(Object.values(data.events).some(v=>!Array.isArray(v)||v.some(x=>typeof x!=='string')))throw Error('Неверный календарь');if(data.bookmarks&&(!Array.isArray(data.bookmarks)||data.bookmarks.some(b=>typeof b.name!=='string'||typeof b.url!=='string'||!/^https?:\/\//i.test(b.url))))throw Error('Неверные закладки');const ids=new Set(),nodes=[];for(const n of data.nodes){if(ids.has(n.id))throw Error('Повторяющийся ID');ids.add(n.id);const {data:encoded,...meta}=n;if(n.kind==='file'){if(typeof encoded!=='string'||!/^data:[^,]*;base64,/.test(encoded))throw Error('Неверное содержимое файла');const bytes=Uint8Array.from(atob(encoded.split(',')[1]),c=>c.charCodeAt(0));meta.blob=new Blob([bytes],{type:typeof n.type==='string'?n.type:''});meta.size=meta.blob.size}nodes.push(meta)}const model=new FileSystemModel(nodes);model.validate();return model}
function applySystemSettings(){applySettings();document.body.classList.toggle('reduce-motion',!!settings.reduceMotion);document.body.classList.toggle('large-type',settings.fontSize===15);$('#widgets').hidden=settings.widgets===false;save('settings',settings)}
function lockScreen(){closeOverlay();let lock=$('#lock-screen');if(!lock){lock=document.createElement('div');lock.id='lock-screen';document.body.append(lock)}lock.innerHTML=`<div><div class="lock-time">${new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</div><p>${new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</p><button class="soft-button" data-unlock>Вернуться в Forma →</button><small>Экран паузы · без парольной защиты</small></div>`;$('[data-unlock]',lock).onclick=()=>lock.remove();$('[data-unlock]',lock).focus()}
function shellWords(line){const tokens=[];const re=/"([^"\\]*(?:\\.[^"\\]*)*)"|'([^']*)'|([^\s]+)/g;let m;while((m=re.exec(line)))tokens.push(m[1]!==undefined?m[1].replace(/\\"/g,'"'):m[2]!==undefined?m[2]:m[3]);return tokens}
function renderTerminal(){const root=body('terminal');root.innerHTML='<div class="terminal"><pre>Forma Shell 2.0 · виртуальные диски IndexedDB\nВведите help. Пути с пробелами заключайте в кавычки.\n\n</pre><form><span data-prompt>guest@forma %</span><input aria-label="Команда терминала" autocomplete="off" spellcheck="false"></form></div>';let cwd=diskRoot(),history=[],historyIndex=0;const out=$('pre',root),input=$('input',root),prompt=$('[data-prompt]',root);const refreshPrompt=()=>{if(!VFS.model.nodes.has(cwd)||VFS.model.get(cwd).deleted||VFS.model.get(cwd).kind==='file')cwd=diskRoot();prompt.textContent='guest@forma '+VFS.model.get(cwd).name+' %'};refreshPrompt();const resolve=p=>VFS.model.resolve(p,cwd);const target=p=>{if(!p)throw Error('Укажите имя или путь');const index=p.lastIndexOf('/');return index<0?{parent:cwd,name:p}:{parent:resolve(p.slice(0,index)||'/').id,name:p.slice(index+1)}};
  $('form',root).onsubmit=async e=>{e.preventDefault();const line=input.value.trim();if(!line)return;history.push(line);historyIndex=history.length;input.value='';input.disabled=true;out.textContent+=prompt.textContent+' '+line+'\n';try{const [cmd,...args]=shellWords(line);let result='';refreshPrompt();switch(cmd){case 'help':result='ls [путь]             содержимое папки\ndisks                 виртуальные диски\npwd                   текущий путь\ncd <путь>             перейти в папку\nmkdir <имя>           создать папку\ntouch <имя>           создать файл\ncat <файл>            прочитать текст (до 1 МБ)\nwrite <файл> <текст>   записать текст\ncp <путь> <папка>      скопировать\nmv <путь> <папка>      переместить\nrm <путь>             в корзину\nopen <путь|app>       открыть файл или приложение\napps                  приложения\nps                    открытые приложения\nkill <app>            закрыть приложение\ndf                    использование дисков\necho <текст>          вывести текст\ndate · whoami · clear';break;case 'disks':result=VFS.model.all().filter(n=>n.kind==='disk').map(n=>VFS.model.path(n.id)).join('\n');break;case 'pwd':result=VFS.model.path(cwd);break;case 'ls':{const n=resolve(args[0]);VFS.model.folder(n.id);result=VFS.model.children(n.id).map(x=>(x.kind==='folder'?'[DIR] ':'      ')+x.name+(x.kind==='file'?'  '+sizeLabel(x.size):'')).join('\n')||'(пусто)';break}case 'cd':{const next=resolve(args[0]);VFS.model.folder(next.id);cwd=next.id;break}case 'mkdir':case 'touch':{const dest=target(args[0]);await VFS.mutate(m=>m.create(dest.parent,dest.name,cmd==='mkdir'?'folder':'file'));result='Создано';break}case 'cat':{const n=resolve(args[0]);if(n.kind!=='file')throw Error('Это не файл');if(n.size>1024*1024)throw Error('Для cat доступны файлы до 1 МБ');result=await n.blob.text();break}case 'write':{const n=resolve(args[0]);await VFS.mutate(m=>m.write(n.id,new Blob([args.slice(1).join(' ')],{type:'text/plain'})));result='Сохранено';break}case 'cp':case 'mv':{if(args.length!==2)throw Error('Укажите источник и папку назначения');const src=resolve(args[0]),dest=resolve(args[1]);await VFS.mutate(m=>cmd==='cp'?m.copy(src.id,dest.id):m.move(src.id,dest.id));result=cmd==='cp'?'Скопировано':'Перемещено';break}case 'rm':if(!args[0])throw Error('Укажите путь');await VFS.mutate(m=>m.trash(resolve(args[0]).id));result='Перемещено в корзину';break;case 'open':if(apps[args[0]])openApp(args[0]);else{const n=resolve(args[0]);if(n.kind==='file')openFile(n);else navigateFiles(n.id)}break;case 'apps':result=Object.entries(apps).map(([id,a])=>id.padEnd(12)+a.name).join('\n');break;case 'ps':result=Object.entries(wins).map(([id,w])=>id.padEnd(12)+(w.style.display==='none'?'свёрнуто':'открыто')).join('\n');break;case 'kill':if(!wins[args[0]])throw Error('Приложение не запущено');closeApp(args[0]);break;case 'df':result=VFS.model.all().filter(n=>n.kind==='disk').map(n=>n.name+': '+sizeLabel(VFS.bytes(n.id))).join('\n')+'\nДиски используют общую квоту браузера.';break;case 'echo':result=args.join(' ');break;case 'date':result=new Date().toLocaleString('ru-RU');break;case 'whoami':result=settings.name||'guest';break;case 'clear':out.textContent='';break;default:throw Error('Неизвестная команда. Введите help.')}if(result)out.textContent+=result+'\n'}catch(error){out.textContent+='Ошибка: '+error.message+'\n'}finally{if(root.isConnected){input.disabled=false;refreshPrompt();input.focus();$('.terminal',root).scrollTop=1e8}}};input.onkeydown=e=>{if(e.key==='ArrowUp'){e.preventDefault();historyIndex=Math.max(0,historyIndex-1);input.value=history[historyIndex]||''}if(e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.min(history.length,historyIndex+1);input.value=history[historyIndex]||''}};input.focus()}
const priorAbout=about;about=function(){settingsSection='system';openApp('settings');renderSettings()};$('#brand').onclick=()=>{const p=showPanel('<h3>Forma OS</h3><button data-system-about>О системе</button><button data-system-tasks>Диспетчер приложений</button><button data-system-settings>Настройки</button><button data-system-lock>Экран паузы</button>');$('[data-system-about]',p).onclick=about;$('[data-system-tasks]',p).onclick=()=>openApp('tasks');$('[data-system-settings]',p).onclick=()=>openApp('settings');$('[data-system-lock]',p).onclick=lockScreen};$('#help').onclick=()=>{settingsSection='behavior';openApp('settings');renderSettings()};
document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.shiftKey&&e.key==='Escape'){e.preventDefault();openApp('tasks')}});
window.addEventListener('beforeunload',e=>{if(editorDirty){e.preventDefault();e.returnValue=''}});
$('#view-menu').onclick=()=>{Object.values(wins).forEach(w=>w.style.display='none');syncActiveApp();rememberSession()};
refreshDock();applySystemSettings();document.addEventListener('fschange',fsChanged);
VFS.init().then(()=>{fsReady=true;fsChanged();if(settings.restoreSession){const session=read('session',[]);for(const s of session)if(apps[s.id]&&!['editor','preview'].includes(s.id)){openApp(s.id);if(s.minimized)wins[s.id].style.display='none'}syncActiveApp()}}).catch(e=>{fsFailure='Не удалось открыть хранилище. Разрешите данные сайта и обновите страницу.';reportError(e);$('.storage-widget .widget-caption').textContent=fsFailure});
